macro_rules! my_vec {
    () => {
        Vec::new()
    };
    ( $( $x:expr ),* $(,)? ) => {
        {
            let mut temp_vec = Vec::new();
            $(
                temp_vec.push($x);
            )*
            temp_vec
        }
    };
}

fn main() {
    let empty: Vec<i32> = my_vec![];
    let v = my_vec![1, 2, 3,];
    println!("{empty:?} {v:?}");
}

