macro_rules! max {
    ($x:expr) => { $x };
    ($x:expr, $($rest:expr),+) => {
        {
            let a = $x;
            let b = max!($($rest),+);
            if a > b { a } else { b }
        }
    };
}

macro_rules! getters {
    ($name:ident { $($field:ident : $ty:ty),* $(,)? }) => {
        struct $name {
            $($field: $ty),*
        }

        impl $name {
            $(
                fn $field(&self) -> &$ty {
                    &self.$field
                }
            )*
        }
    };
}

getters!(Book { title: String, pages: u32 });

fn main() {
    println!("{}", max!(3));
    println!("{}", max!(3, 9, 4, 1));

    let b = Book { title: String::from("The Book"), pages: 550 };
    println!("{} has {} pages", b.title(), b.pages());
}

macro_rules! square_twice {
    ($e:expr) => {{
        let x = $e * $e;
        x * x
    }};
}

fn main() {
    let x = 3;
    let r = square_twice!(x + 1);
    println!("x is still {x}, result {r}");
}

use proc_macro::TokenStream;
use quote::quote;

#[proc_macro_derive(HelloMacro)]
pub fn hello_macro_derive(input: TokenStream) -> TokenStream {
    // parse the tokens into a syntax tree
    let ast = syn::parse(input).unwrap();

    // build the trait implementation
    impl_hello_macro(&ast)
}

fn impl_hello_macro(ast: &syn::DeriveInput) -> TokenStream {
    let name = &ast.ident;
    let generated = quote! {
        impl HelloMacro for #name {
            fn hello_macro() {
                println!("Hello, Macro! My name is {}!", stringify!(#name));
            }
        }
    };
    generated.into()
}

// a user of the derive writes only this:
use hello_macro::HelloMacro;
use hello_macro_derive::HelloMacro;

#[derive(HelloMacro)]
struct Pancakes;

fn main() {
    Pancakes::hello_macro(); // prints: Hello, Macro! My name is Pancakes!
}

